const form = $('On Blog Request').first().json;
const topic = form['Blog Topic'] || '';
const keyword = form['Target Keyword'] || '';
const sitemapUrl = (form['Sitemap URL'] || '').trim();

let urls = [];
let linkStatus = 'No sitemap URL was provided.';

if (sitemapUrl) {
  let body = '';
  try {
    const res = $input.first().json;
    body = typeof res === 'string' ? res : (res.data || res.body || '');
    if (typeof body !== 'string') body = '';
  } catch (e) {
    body = '';
  }

  if (!body) {
    linkStatus = 'Sitemap could not be read - writing without internal links.';
  } else {
    const matches = body.match(/<loc>\s*([^<\s]+)\s*<\/loc>/gi) || [];
    urls = matches
      .map(m => m.replace(/<\/?loc>/gi, '').trim())
      .filter(u => /^https?:\/\//i.test(u))
      .filter(u => !/\.(xml|jpg|jpeg|png|gif|webp|svg|pdf|css|js)$/i.test(u));

    // De-duplicate
    urls = Array.from(new Set(urls));

    if (!urls.length) {
      linkStatus = 'Sitemap contained no usable page URLs - this may be a sitemap index. Writing without internal links.';
    }
  }
}

// Rank URLs by how well their slug matches the topic, so the AI gets relevant candidates first
const stop = new Set(['the','a','an','and','or','for','to','of','in','on','with','how','what','why','is','are','best','your','you','from','that','this']);
const terms = (topic + ' ' + keyword)
  .toLowerCase()
  .split(/[^a-z0-9]+/)
  .filter(w => w.length > 2 && !stop.has(w));

function score(url) {
  const slug = url.toLowerCase();
  return terms.reduce((n, t) => n + (slug.includes(t) ? 1 : 0), 0);
}

const ranked = urls
  .map(u => ({ url: u, score: score(u) }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 20)
  .map(o => o.url);

if (ranked.length) {
  linkStatus = `${urls.length} URLs found in sitemap, ${ranked.length} most relevant offered to the writer.`;
}

return [{
  json: {
    topic,
    keyword,
    wordCount: form['Target Word Count'] || '1200',
    linkStatus,
    internalLinks: ranked.length ? ranked.join('\n') : 'NONE'
  }
}];

const raw = String($input.item.json.text || '').trim();
const attempt = $runIndex;

let cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```\s*$/, '').trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start !== -1 && end !== -1 && end > start) {
  cleaned = cleaned.slice(start, end + 1);
}

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = null;
}

// If the model didn't return usable JSON, keep the draft we already had and stop looping.
if (!parsed || typeof parsed.improvedDraft !== 'string' || !parsed.improvedDraft.trim()) {
  return {
    json: {
      draft: $('Prepare Draft').first().json.draft || '',
      passed: true,
      attempt,
      issues: 'Audit response could not be parsed as JSON - keeping the last good draft unchanged.'
    }
  };
}

const issues = Array.isArray(parsed.issues)
  ? parsed.issues.filter(Boolean).join('; ')
  : String(parsed.issues || '');

return {
  json: {
    draft: parsed.improvedDraft,
    passed: parsed.passed === true,
    attempt,
    issues: issues || 'none'
  }
};

const brief = $('Extract Internal Links').first().json;
const result = $input.item.json;
const post = result.draft || '';

const titleMatch = post.match(/^#\s+(.+)$/m);
const metaMatch = post.match(/\*\*Meta description:\*\*\s*(.+)/i);

return {
  json: {
    title: titleMatch ? titleMatch[1].trim() : brief.topic,
    metaDescription: metaMatch ? metaMatch[1].trim() : '',
    post,
    wordCount: post.split(/\s+/).filter(Boolean).length,
    auditPassed: result.passed,
    auditNotes: result.issues || 'none',
    internalLinks: brief.linkStatus
  }
};
